-- READ ONLY. Application metadata only: no customer rows, setting values or secrets.
SELECT jsonb_build_object(
  'captured_at', now(),
  'settings', (SELECT jsonb_agg(jsonb_build_object('key',key,'type',jsonb_typeof(value),'public',is_public,'campus_scoped',campus_id IS NOT NULL) ORDER BY key) FROM public.system_settings),
  'flags', (SELECT jsonb_agg(jsonb_build_object('name',feature_name,'enabled',is_active,'campus_scoped',campus_id IS NOT NULL) ORDER BY feature_name) FROM public.feature_flags),
  'policies', (SELECT jsonb_agg(to_jsonb(p) ORDER BY schemaname,tablename,policyname) FROM pg_policies p WHERE schemaname IN ('public','hg_internal')),
  'tables', (SELECT jsonb_agg(jsonb_build_object('schema',n.nspname,'name',c.relname,'rls',c.relrowsecurity,'force_rls',c.relforcerowsecurity,
    'anon',jsonb_build_object('select',has_table_privilege('anon',c.oid,'SELECT'),'insert',has_table_privilege('anon',c.oid,'INSERT'),'update',has_table_privilege('anon',c.oid,'UPDATE'),'delete',has_table_privilege('anon',c.oid,'DELETE')),
    'authenticated',jsonb_build_object('select',has_table_privilege('authenticated',c.oid,'SELECT'),'insert',has_table_privilege('authenticated',c.oid,'INSERT'),'update',has_table_privilege('authenticated',c.oid,'UPDATE'),'delete',has_table_privilege('authenticated',c.oid,'DELETE')))
    ORDER BY n.nspname,c.relname) FROM pg_class c JOIN pg_namespace n ON n.oid=c.relnamespace WHERE n.nspname IN ('public','hg_internal') AND c.relkind IN ('r','p')),
  'views', (SELECT jsonb_agg(jsonb_build_object('name',c.relname,'options',c.reloptions,'anon',has_table_privilege('anon',c.oid,'SELECT'),'authenticated',has_table_privilege('authenticated',c.oid,'SELECT')) ORDER BY c.relname) FROM pg_class c JOIN pg_namespace n ON n.oid=c.relnamespace WHERE n.nspname='public' AND c.relkind='v'),
  'triggers', (SELECT jsonb_agg(jsonb_build_object('schema',n.nspname,'table',c.relname,'name',t.tgname,'enabled',t.tgenabled,'function',t.tgfoid::regprocedure::text,'definition',pg_get_triggerdef(t.oid)) ORDER BY n.nspname,c.relname,t.tgname) FROM pg_trigger t JOIN pg_class c ON c.oid=t.tgrelid JOIN pg_namespace n ON n.oid=c.relnamespace WHERE NOT t.tgisinternal AND n.nspname IN ('public','hg_internal')),
  'indexes', (SELECT jsonb_agg(jsonb_build_object('table',t.relname,'name',c.relname,'definition',pg_get_indexdef(i.indexrelid),'valid',i.indisvalid,'unique',i.indisunique,'primary',i.indisprimary,'key',i.indkey::text,'predicate',pg_get_expr(i.indpred,i.indrelid)) ORDER BY t.relname,c.relname) FROM pg_index i JOIN pg_class c ON c.oid=i.indexrelid JOIN pg_class t ON t.oid=i.indrelid JOIN pg_namespace n ON n.oid=t.relnamespace WHERE n.nspname IN ('public','hg_internal')),
  'functions', (SELECT jsonb_agg(jsonb_build_object('signature',p.oid::regprocedure::text,'name',p.proname,'schema',n.nspname,'definer',p.prosecdef,'config',p.proconfig,'anon',has_function_privilege('anon',p.oid,'EXECUTE'),'authenticated',has_function_privilege('authenticated',p.oid,'EXECUTE'),'service',has_function_privilege('service_role',p.oid,'EXECUTE'),'kind',p.prokind) ORDER BY n.nspname,p.proname,p.oid) FROM pg_proc p JOIN pg_namespace n ON n.oid=p.pronamespace WHERE n.nspname IN ('public','hg_internal')),
  'migrations', (SELECT jsonb_agg(jsonb_build_object('version',version,'name',name) ORDER BY version) FROM supabase_migrations.schema_migrations),
  'extensions', (SELECT jsonb_agg(jsonb_build_object('name',e.extname,'schema',n.nspname,'relocatable',e.extrelocatable,'version',e.extversion)) FROM pg_extension e JOIN pg_namespace n ON n.oid=e.extnamespace)
) AS inventory;
